-- BiletFlow events management: inventory indexes and order number identity.
-- PostgreSQL 15+. Idempotent — safe to run on every startup.
-- Run AFTER migrate_001.sql (depends on orders / order_items / tickets).

BEGIN;

-- migrate_001 declares orders.order_number as GENERATED ALWAYS AS IDENTITY. The
-- ORM assigns the value from Python so inserts also work on the SQLite test
-- fallback (which cannot auto-generate a BIGINT identity). Switch the column to
-- GENERATED BY DEFAULT so it accepts those explicit values.
ALTER TABLE orders ALTER COLUMN order_number DROP IDENTITY IF EXISTS;
ALTER TABLE orders ALTER COLUMN order_number ADD GENERATED BY DEFAULT AS IDENTITY;

-- Inventory aggregation filters order_items by ticket type and tickets by
-- status; both are hot paths for the sold/reserved/checked-in counters.
CREATE INDEX IF NOT EXISTS idx_order_items_ticket_type
    ON order_items (ticket_type_id);
CREATE INDEX IF NOT EXISTS idx_tickets_status
    ON tickets (status);

COMMIT;
